use serde :: { Deserialize , Serialize } ; use strum_macros :: EnumString ; use std :: str :: FromStr ; use super :: * ; # [doc = " HTTP client configuration with support for timeouts, connection pooling,"] # [doc = " redirects, DNS resolution, TLS settings, and HTTP/2 configuration."] # [doc = ""] # [doc = " # TLS Configuration"] # [doc = " The `min_tls_version` and `max_tls_version` fields allow you to specify"] # [doc = " TLS protocol version constraints. These are optional and when `None`,"] # [doc = " the TLS library defaults will be used."] # [doc = ""] # [doc = " # HTTP/2 Configuration"] # [doc = " The HTTP/2 settings control adaptive window sizing, keep-alive behavior,"] # [doc = " and connection management for HTTP/2 connections."] # [doc = ""] # [doc = " # Environment Variables"] # [doc = " All HttpConfig fields can be configured via environment variables:"] # [doc = " - `FORGE_HTTP_CONNECT_TIMEOUT`: Connection timeout in seconds (default: 30)"] # [doc = " - `FORGE_HTTP_READ_TIMEOUT`: Read timeout in seconds (default: 900)"] # [doc = " - `FORGE_HTTP_POOL_IDLE_TIMEOUT`: Pool idle timeout in seconds (default: 90)"] # [doc = " - `FORGE_HTTP_POOL_MAX_IDLE_PER_HOST`: Max idle connections per host"] # [doc = "   (default: 5)"] # [doc = " - `FORGE_HTTP_MAX_REDIRECTS`: Maximum redirects to follow (default: 10)"] # [doc = " - `FORGE_HTTP_USE_HICKORY`: Use Hickory DNS resolver (default: false)"] # [doc = " - `FORGE_HTTP_TLS_BACKEND`: TLS backend (\"default\" or \"rustls\", default:"] # [doc = "   \"default\")"] # [doc = " - `FORGE_HTTP_MIN_TLS_VERSION`: Minimum TLS version (\"1.0\", \"1.1\", \"1.2\","] # [doc = "   \"1.3\")"] # [doc = " - `FORGE_HTTP_MAX_TLS_VERSION`: Maximum TLS version (\"1.0\", \"1.1\", \"1.2\","] # [doc = "   \"1.3\")"] # [doc = " - `FORGE_HTTP_ADAPTIVE_WINDOW`: Enable HTTP/2 adaptive window (default:"] # [doc = "   true)"] # [doc = " - `FORGE_HTTP_KEEP_ALIVE_INTERVAL`: Keep-alive interval in seconds (default:"] # [doc = "   60, use \"none\"/\"disabled\" to disable)"] # [doc = " - `FORGE_HTTP_KEEP_ALIVE_TIMEOUT`: Keep-alive timeout in seconds (default:"] # [doc = "   10)"] # [doc = " - `FORGE_HTTP_KEEP_ALIVE_WHILE_IDLE`: Keep-alive while idle (default: true)"] # [doc = " - `FORGE_HTTP_ACCEPT_INVALID_CERTS`: Accept invalid certificates (default:"] # [doc = "   false) - USE WITH CAUTION"] # [doc = " - `FORGE_HTTP_ROOT_CERT_PATHS`: Paths to root certificate files (PEM, CRT,"] # [doc = "   CER format), multiple paths separated by commas"] # [doc = ""] # [doc = " # Example"] # [doc = " ```"] # [doc = " use forge_domain::{HttpConfig, TlsVersion, TlsBackend};"] # [doc = ""] # [doc = " let config = HttpConfig {"] # [doc = "     connect_timeout: 30,"] # [doc = "     min_tls_version: Some(TlsVersion::V1_2),"] # [doc = "     max_tls_version: Some(TlsVersion::V1_3),"] # [doc = "     tls_backend: TlsBackend::Rustls,"] # [doc = "     adaptive_window: true,"] # [doc = "     keep_alive_interval: Some(60),"] # [doc = "     ..HttpConfig::default()"] # [doc = " };"] # [doc = " ```"] # [derive (Debug , Clone , PartialEq , Serialize , Deserialize , fake :: Dummy)] # [serde (rename_all = "camelCase")] pub struct HttpConfig { pub connect_timeout : u64 , pub read_timeout : u64 , pub pool_idle_timeout : u64 , pub pool_max_idle_per_host : usize , pub max_redirects : usize , pub hickory : bool , pub tls_backend : TlsBackend , # [doc = " Minimum TLS protocol version to use. When `None`, uses TLS library"] # [doc = " default."] pub min_tls_version : Option < TlsVersion > , # [doc = " Maximum TLS protocol version to use. When `None`, uses TLS library"] # [doc = " default."] pub max_tls_version : Option < TlsVersion > , # [doc = " Adaptive window sizing for improved flow control."] pub adaptive_window : bool , # [doc = " Keep-alive interval in seconds. When `None`, keep-alive is"] # [doc = " disabled."] pub keep_alive_interval : Option < u64 > , # [doc = " Keep-alive timeout in seconds."] pub keep_alive_timeout : u64 , # [doc = " Keep-alive while connection is idle."] pub keep_alive_while_idle : bool , # [doc = " Accept invalid certificates. This should be used with caution."] pub accept_invalid_certs : bool , # [doc = " Paths to root certificate files (PEM, CRT, CER format). Multiple paths"] # [doc = " can be separated by commas."] pub root_cert_paths : Option < Vec < String > > , }